4	//! Event types for KV cache coordination across workers.
5	//!
6	//! This module defines the event protocol used to track block registrations
7	//! and removals across distributed workers. Events are emitted when blocks
8	//! at power-of-2 positions are registered or released.
9	//!
10	//! The event types are organized in three layers:
11	//! - [`KvCacheEvent`]: Individual events for internal streaming
12	//! - [`KvCacheEvents`]: Batched events with multiple sequence hashes
13	//! - [`KvbmCacheEvents`]: Wire format with instance/cluster context
14	
15	use serde::Deserialize;
16	use serde::Serialize;
17	use tokio::sync::broadcast;
18	
19	use crate::SequenceHash;
20	
21	/// Instance identifier for a worker node (u128).
22	pub type InstanceId = u128;
23	
24	/// Individual event emitted when a block is registered or removed.
25	///
26	/// This is the simplified internal event type. Instance and cluster context
27	/// are provided at the batch level via [`KvbmCacheEvents`].
28	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
29	pub enum KvCacheEvent {
30	    /// A block has been registered in a worker's cache.
31	    Create(SequenceHash),
32	    /// A block has been removed from a worker's cache.
33	    Remove(SequenceHash),
34	}
35	
36	/// Batched events with multiple sequence hashes.
37	///
38	/// Events are batched by type - either all creates or all removes.
39	/// Create events are sorted by position ascending (low to high) for efficient
40	/// radix tree insertion. Remove events are sorted by position descending
41	/// (high to low) for efficient radix tree removal.
42	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
43	pub enum KvCacheEvents {
44	    /// Multiple blocks have been registered.
45	    Create(Vec<SequenceHash>),
46	    /// Multiple blocks have been removed.
47	    Remove(Vec<SequenceHash>),
48	    /// Publisher is shutting down.
49	    Shutdown,
50	}
51	
52	/// Wire format for publishing batched events.
53	///
54	/// This is the complete message format sent over the wire, including
55	/// instance context that applies to all events in the batch.
56	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
57	pub struct KvbmCacheEvents {
58	    /// The batched events.
59	    pub events: KvCacheEvents,
60	    /// The worker instance that generated these events.
61	    pub instance_id: InstanceId,
62	}
63	
64	/// RAII handle that triggers a Remove event when dropped.
65	///
66	/// This handle is attached to a [`crate::registry::BlockRegistrationHandle`] as an [`std::sync::Arc<dyn std::any::Any>`].
67	/// When all references to the block are dropped, this handle's Drop implementation
68	/// sends a Remove event to clean up the hub's tracking state.
69	pub struct EventReleaseHandle {
70	    seq_hash: SequenceHash,
71	    event_tx: broadcast::Sender<KvCacheEvent>,
72	}
